import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static boolean hasMore() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        if (c == -1) return false;
        ptr--;
        return true;
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int q = nextInt();
        int[] dx = {0, 1, 0, -1}, dy = {1, 0, -1, 0};
        StringBuilder out = new StringBuilder();
        for (int t = 0; t < q; t++) {
            String s = next();
            int x = 0, y = 0, d = 0;
            for (int i = 0; i < s.length(); i++) {
                char c = s.charAt(i);
                if (c == 'L') d = (d + 1) % 4;
                else if (c == 'R') d = (d + 3) % 4;
                else {
                    x += dx[d];
                    y += dy[d];
                }
            }
            // bounded iff back at the origin or facing a new direction after one pass
            out.append((x == 0 && y == 0) || d != 0 ? "YES\n" : "NO\n");
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	q := int(nextInt())
	dx := [4]int{0, 1, 0, -1}
	dy := [4]int{1, 0, -1, 0}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for t := 0; t < q; t++ {
		s := nextToken()
		x, y, d := 0, 0, 0
		for i := 0; i < len(s); i++ {
			switch s[i] {
			case 'L':
				d = (d + 1) % 4
			case 'R':
				d = (d + 3) % 4
			default:
				x += dx[d]
				y += dy[d]
			}
		}
		// bounded iff back at the origin or facing a new direction after one pass
		if x == 0 && y == 0 || d != 0 {
			w.WriteString("YES\n")
		} else {
			w.WriteString("NO\n")
		}
	}
}
